<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Conway's Game of Life</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #1a1a2e;
    color: #e0e0e0;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    padding: 20px;
  }
  h1 {
    font-size: 2rem;
    margin-bottom: 16px;
    color: #00ff88;
    text-shadow: 0 0 20px rgba(0,255,136,0.3);
    letter-spacing: 2px;
  }
  #controls {
    display: flex;
    gap: 12px;
    margin-bottom: 20px;
    flex-wrap: wrap;
    justify-content: center;
  }
  #controls button {
    background: #16213e;
    color: #e0e0e0;
    border: 2px solid #0f3460;
    padding: 10px 24px;
    border-radius: 8px;
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.2s ease;
    font-weight: 600;
    letter-spacing: 1px;
  }
  #controls button:hover {
    background: #0f3460;
    border-color: #00ff88;
    color: #00ff88;
    box-shadow: 0 0 12px rgba(0,255,136,0.3);
  }
  #controls button:active {
    transform: scale(0.95);
  }
  #controls button.active {
    background: #00ff88;
    color: #1a1a2e;
    border-color: #00ff88;
  }
  #life {
    border: 2px solid #0f3460;
    border-radius: 4px;
    cursor: crosshair;
    box-shadow: 0 0 30px rgba(0,255,136,0.1);
    display: block;
  }
  #gen-display {
    margin-top: 14px;
    font-size: 0.95rem;
    color: #888;
    letter-spacing: 1px;
  }
  #gen-display span {
    color: #00ff88;
    font-weight: bold;
  }
</style>
</head>
<body>
<h1>🧬 Game of Life</h1>
<div id="controls">
  <button id="step">⏭ Step</button>
  <button id="play">▶ Play</button>
  <button id="random">🎲 Random</button>
  <button id="clear">🗑 Clear</button>
</div>
<canvas id="life" width="400" height="400"></canvas>
<div id="gen-display">Generation: <span id="gen-count">0</span> &nbsp;|&nbsp; Alive: <span id="alive-count">0</span></div>

<script>
(function() {
  const W = 40;
  const H = 40;
  const CELL = 10; // 400/40 = 10px per cell

  const canvas = document.getElementById('life');
  const ctx = canvas.getContext('2d');

  // Two buffers for simultaneous update
  let grid = new Int8Array(W * H);
  let nextGrid = new Int8Array(W * H);
  let playing = false;
  let genCount = 0;
  let animId = null;

  function idx(x, y) { return y * W + x; }

  function draw() {
    // Background
    ctx.fillStyle = '#0d1117';
    ctx.fillRect(0, 0, W * CELL, H * CELL);

    // Grid lines
    ctx.strokeStyle = '#162032';
    ctx.lineWidth = 0.5;
    for (let x = 0; x <= W; x++) {
      ctx.beginPath();
      ctx.moveTo(x * CELL, 0);
      ctx.lineTo(x * CELL, H * CELL);
      ctx.stroke();
    }
    for (let y = 0; y <= H; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * CELL);
      ctx.lineTo(W * CELL, y * CELL);
      ctx.stroke();
    }

    // Alive cells
    let alive = 0;
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        if (grid[idx(x, y)]) {
          alive++;
          // Glowing alive cell
          ctx.fillStyle = '#00ff88';
          ctx.shadowColor = '#00ff88';
          ctx.shadowBlur = 6;
          ctx.fillRect(x * CELL + 1, y * CELL + 1, CELL - 2, CELL - 2);
          ctx.shadowBlur = 0;
        }
      }
    }

    document.getElementById('gen-count').textContent = genCount;
    document.getElementById('alive-count').textContent = alive;
  }

  function countNeighbours(x, y) {
    let count = 0;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = x + dx;
        const ny = y + dy;
        if (nx >= 0 && nx < W && ny >= 0 && ny < H) {
          count += grid[idx(nx, ny)];
        }
        // Out of bounds counts as 0 (dead) — edges are dead
      }
    }
    return count;
  }

  function computeStep() {
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const i = idx(x, y);
        const n = countNeighbours(x, y);
        const alive = grid[i];
        if (alive) {
          // B3/S23: live cell survives with 2 or 3 neighbours
          nextGrid[i] = (n === 2 || n === 3) ? 1 : 0;
        } else {
          // Dead cell becomes alive with exactly 3 neighbours
          nextGrid[i] = (n === 3) ? 1 : 0;
        }
      }
    }
    // Swap buffers
    const tmp = grid;
    grid = nextGrid;
    nextGrid = tmp;
    genCount++;
  }

  function step() {
    computeStep();
    draw();
  }

  function clear() {
    grid.fill(0);
    nextGrid.fill(0);
    genCount = 0;
    draw();
  }

  function randomize() {
    for (let i = 0; i < W * H; i++) {
      grid[i] = Math.random() < 0.3 ? 1 : 0;
    }
    genCount = 0;
    draw();
  }

  function getCell(x, y) {
    if (x < 0 || x >= W || y < 0 || y >= H) return 0;
    return grid[idx(x, y)];
  }

  function setCell(x, y, v) {
    if (x >= 0 && x < W && y >= 0 && y < H) {
      grid[idx(x, y)] = v ? 1 : 0;
      draw();
    }
  }

  // Toggle cell and redraw (for painting)
  function toggleCell(x, y) {
    if (x >= 0 && x < W && y >= 0 && y < H) {
      grid[idx(x, y)] = grid[idx(x, y)] ? 0 : 1;
      draw();
    }
  }

  // Mouse interaction
  let painting = false;
  let paintValue = -1; // -1 means toggle, otherwise set to this value

  canvas.addEventListener('mousedown', function(e) {
    e.preventDefault();
    painting = true;
    const rect = canvas.getBoundingClientRect();
    const scaleX = (W * CELL) / rect.width;
    const scaleY = (H * CELL) / rect.height;
    const mx = (e.clientX - rect.left) * scaleX;
    const my = (e.clientY - rect.top) * scaleY;
    const cx = Math.floor(mx / CELL);
    const cy = Math.floor(my / CELL);
    // Determine if we're painting alive or dead
    if (cx >= 0 && cx < W && cy >= 0 && cy < H) {
      paintValue = grid[idx(cx, cy)] ? 0 : 1;
      grid[idx(cx, cy)] = paintValue;
      draw();
    }
  });

  canvas.addEventListener('mousemove', function(e) {
    if (!painting) return;
    const rect = canvas.getBoundingClientRect();
    const scaleX = (W * CELL) / rect.width;
    const scaleY = (H * CELL) / rect.height;
    const mx = (e.clientX - rect.left) * scaleX;
    const my = (e.clientY - rect.top) * scaleY;
    const cx = Math.floor(mx / CELL);
    const cy = Math.floor(my / CELL);
    if (cx >= 0 && cx < W && cy >= 0 && cy < H) {
      grid[idx(cx, cy)] = paintValue;
      draw();
    }
  });

  window.addEventListener('mouseup', function() {
    painting = false;
    paintValue = -1;
  });

  // Touch support
  canvas.addEventListener('touchstart', function(e) {
    e.preventDefault();
    const touch = e.touches[0];
    const rect = canvas.getBoundingClientRect();
    const scaleX = (W * CELL) / rect.width;
    const scaleY = (H * CELL) / rect.height;
    const mx = (touch.clientX - rect.left) * scaleX;
    const my = (touch.clientY - rect.top) * scaleY;
    const cx = Math.floor(mx / CELL);
    const cy = Math.floor(my / CELL);
    if (cx >= 0 && cx < W && cy >= 0 && cy < H) {
      paintValue = grid[idx(cx, cy)] ? 0 : 1;
      grid[idx(cx, cy)] = paintValue;
      draw();
    }
  }, { passive: false });

  canvas.addEventListener('touchmove', function(e) {
    e.preventDefault();
    const touch = e.touches[0];
    const rect = canvas.getBoundingClientRect();
    const scaleX = (W * CELL) / rect.width;
    const scaleY = (H * CELL) / rect.height;
    const mx = (touch.clientX - rect.left) * scaleX;
    const my = (touch.clientY - rect.top) * scaleY;
    const cx = Math.floor(mx / CELL);
    const cy = Math.floor(my / CELL);
    if (cx >= 0 && cx < W && cy >= 0 && cy < H) {
      grid[idx(cx, cy)] = paintValue;
      draw();
    }
  }, { passive: false });

  canvas.addEventListener('touchend', function() {
    painting = false;
    paintValue = -1;
  });

  // Button handlers
  document.getElementById('step').addEventListener('click', step);

  document.getElementById('play').addEventListener('click', function() {
    playing = !playing;
    const btn = document.getElementById('play');
    if (playing) {
      btn.textContent = '⏸ Pause';
      btn.classList.add('active');
      loop();
    } else {
      btn.textContent = '▶ Play';
      btn.classList.remove('active');
      if (animId) {
        cancelAnimationFrame(animId);
        animId = null;
      }
    }
  });

  document.getElementById('random').addEventListener('click', function() {
    if (playing) {
      playing = false;
      document.getElementById('play').textContent = '▶ Play';
      document.getElementById('play').classList.remove('active');
      if (animId) { cancelAnimationFrame(animId); animId = null; }
    }
    randomize();
  });

  document.getElementById('clear').addEventListener('click', function() {
    if (playing) {
      playing = false;
      document.getElementById('play').textContent = '▶ Play';
      document.getElementById('play').classList.remove('active');
      if (animId) { cancelAnimationFrame(animId); animId = null; }
    }
    clear();
  });

  // Animation loop
  let lastTime = 0;
  const TICK = 150; // ms per generation

  function loop(timestamp) {
    if (!playing) return;
    if (!lastTime) lastTime = timestamp;
    if (timestamp - lastTime >= TICK) {
      computeStep();
      draw();
      lastTime = timestamp;
    }
    animId = requestAnimationFrame(loop);
  }

  // Expose API
  window.life = {
    w: W,
    h: H,
    get: getCell,
    set: setCell,
    step: step,
    clear: clear
  };

  // Initial draw
  draw();
})();
</script>
</body>
</html>
